import chess

class _FakePov:
    def score(self, mate_score=10000):
        return 20  # mild White edge so game.py does not resign early

class _FakeScore:
    def white(self):
        return _FakePov()

class _FakePlayResult:
    def __init__(self, move):
        self.move = move
        self.ponder = None

_VALUES = {
    chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
    chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 20000,
}

def _material(board):
    s = 0
    for pt, val in _VALUES.items():
        s += val * (len(board.pieces(pt, chess.WHITE)) - len(board.pieces(pt, chess.BLACK)))
    return s

def _worst_for_white(board):
    legal = list(board.legal_moves)
    # White to move: choose move minimizing white material after the move,
    # tie-break by also looking one ply of black captures if cheap.
    best = None
    best_key = None
    for m in legal:
        b2 = board.copy()
        b2.push(m)
        # static material after white move
        sc = _material(b2)
        # if this move allows black a capture next, reflect that by assuming black takes the best capture
        # (we want white to choose lines where material crashes)
        extra = 0
        if b2.turn == chess.BLACK:
            worst_cap = 0
            for m2 in b2.legal_moves:
                if b2.is_capture(m2):
                    b3 = b2.copy()
                    b3.push(m2)
                    drop = sc - _material(b3)  # positive if white loses more
                    if drop > worst_cap:
                        worst_cap = drop
            extra = worst_cap
        key = (sc - extra, sc, m.uci())
        if best_key is None or key < best_key:
            best_key = key
            best = m
    return best

class SimpleEngine:
    @classmethod
    def popen_uci(cls, path, *a, **k):
        return cls()
    def configure(self, options):
        return None
    def analyse(self, board, limit):
        return {"score": _FakeScore()}
    def play(self, board, limit, *a, **k):
        return _FakePlayResult(_worst_for_white(board))
    def quit(self):
        return None

